/* com.lsy.sicore_v1.user.mapper.insertUser 사용자 등록 */
INSERT INTO TB_USER
(
      USER_ID
    , LOGIN_ID
    , PASSWORD
    , USER_NAME
    , EMAIL
    , PHONE
    , STATUS_CD
    , LOGIN_FAIL_CNT
    , LAST_LOGIN_AT
    , CREATED_AT
    , UPDATED_AT
)
VALUES
(
      #{userId}
    , #{loginId}
    , #{password}
    , #{userName}
    , #{email}
    , #{phone}
    , 'NORMAL'
    , 0
    , SYSDATE
    , SYSDATE
    , SYSDATE
)

